        const pages = yield* Effect.forEach(batch, (item) => (item.underCustomer ? listCustomerNodes(item.parent) : listNodeNodes(item.parent)).pipe(Effect.map((nodes) => nodes.map((node) => ({ node, parent: item.parent })))), { concurrency: 4 });
